CREATE SCHEMA IF NOT EXISTS core_humangrant;

CREATE TABLE IF NOT EXISTS core_humangrant.human_grant_records (
    kind VARCHAR(32) NOT NULL,
    id VARCHAR(128) NOT NULL,
    owner VARCHAR(128),
    expires_at BIGINT,
    payload TEXT NOT NULL,
    PRIMARY KEY (kind, id)
);
CREATE INDEX IF NOT EXISTS idx_core_hg_owner ON core_humangrant.human_grant_records(kind, owner);
CREATE INDEX IF NOT EXISTS idx_core_hg_expiry ON core_humangrant.human_grant_records(expires_at);

CREATE TABLE IF NOT EXISTS core_humangrant.human_grant_gate (
    id INT PRIMARY KEY,
    revision BIGINT NOT NULL DEFAULT 1
);
INSERT INTO core_humangrant.human_grant_gate (id, revision) VALUES (1, 1) ON CONFLICT (id) DO NOTHING;

REVOKE ALL ON SCHEMA core_humangrant FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA core_humangrant FROM PUBLIC;

-- Fresh installation only. The installer supplies the transaction and contract hash.
CREATE SCHEMA core_meta;
CREATE TABLE core_meta.schema_contract (
    singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    version INTEGER NOT NULL CHECK (version > 0),
    fingerprint BYTEA NOT NULL CHECK (octet_length(fingerprint) = 32),
    installed_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

CREATE SCHEMA core_identity;
CREATE TABLE core_identity.accounts (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    kind TEXT NOT NULL CHECK (kind IN ('personal', 'team')),
    service_level SMALLINT NOT NULL DEFAULT 0 CHECK (service_level BETWEEN 0 AND 4),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (id, kind)
);
CREATE TABLE core_identity.users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id > 0),
    personal_account_id BIGINT NOT NULL UNIQUE,
    account_kind TEXT GENERATED ALWAYS AS ('personal'::text) STORED,
    platform_role TEXT NOT NULL DEFAULT 'user'
        CHECK (platform_role IN ('user', 'admin', 'superadmin')),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    auth_version BIGINT NOT NULL DEFAULT 1 CHECK (auth_version > 0),
    FOREIGN KEY (personal_account_id, account_kind) REFERENCES core_identity.accounts(id, kind)
);
CREATE TABLE core_identity.teams (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    account_id BIGINT NOT NULL UNIQUE,
    account_kind TEXT GENERATED ALWAYS AS ('team'::text) STORED,
    owner_user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    created_by_user_id BIGINT NOT NULL UNIQUE REFERENCES core_identity.users(id),
    name TEXT NOT NULL DEFAULT 'Team' CHECK (length(btrim(name)) BETWEEN 1 AND 100),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    FOREIGN KEY (account_id, account_kind) REFERENCES core_identity.accounts(id, kind)
);
CREATE INDEX teams_owner ON core_identity.teams(owner_user_id,id);
-- This row is an authorization generation, not a budget counter. Never delete it
-- on removal, and never reset financial usage when the generation changes.
CREATE TABLE core_identity.memberships (
    team_id BIGINT NOT NULL REFERENCES core_identity.teams(id),
    user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    role TEXT NOT NULL CHECK (role IN ('admin', 'member')),
    can_spend BOOLEAN NOT NULL DEFAULT FALSE,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    PRIMARY KEY (team_id, user_id)
);
CREATE INDEX memberships_user ON core_identity.memberships(user_id, team_id);
CREATE TABLE core_identity.credentials (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    digest BYTEA NOT NULL UNIQUE CHECK (octet_length(digest) = 32),
    kind TEXT NOT NULL CHECK (kind IN ('session', 'api_key')),
    user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    user_version BIGINT NOT NULL CHECK (user_version > 0),
    owner_account_id BIGINT NOT NULL REFERENCES core_identity.accounts(id),
    personal_billing_preference TEXT
        CHECK (personal_billing_preference IN ('subscription_first', 'wallet_first', 'subscription_only', 'wallet_only')),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    session_started_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    CHECK (kind = 'api_key' OR personal_billing_preference IS NULL)
);
CREATE INDEX credentials_user ON core_identity.credentials(user_id, id);
CREATE INDEX credentials_owner ON core_identity.credentials(owner_account_id, id);
-- Authentication hashes remain separate from optional encrypted recovery
-- material. One-time keys have no recoverable copy.
CREATE TABLE core_identity.api_key_settings (
    credential_id BIGINT PRIMARY KEY REFERENCES core_identity.credentials(id),
    name TEXT NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 128),
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    one_time_reveal BOOLEAN NOT NULL DEFAULT TRUE,
    encrypted_secret BYTEA,
    model_limits_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    model_limits TEXT[] NOT NULL DEFAULT '{}',
    allow_ips INET[] NOT NULL DEFAULT '{}',
    group_name TEXT NOT NULL CHECK (length(group_name) BETWEEN 1 AND 64),
    auto_groups TEXT[] NOT NULL DEFAULT '{}',
    cross_group_retry BOOLEAN NOT NULL DEFAULT FALSE,
    account_balance_read BOOLEAN NOT NULL DEFAULT FALSE,
    accessed_at TIMESTAMPTZ,
    CHECK (cardinality(model_limits) <= 200 AND cardinality(allow_ips) <= 64),
    CHECK (cardinality(auto_groups) <= 16),
    CHECK ((one_time_reveal AND encrypted_secret IS NULL) OR
        (NOT one_time_reveal AND encrypted_secret IS NOT NULL
            AND octet_length(encrypted_secret) BETWEEN 44 AND 300)),
    CHECK (group_name = 'auto' OR (cardinality(auto_groups) = 0 AND NOT cross_group_retry))
);
-- Operator/migration grants, never inferred from the existence of a route.
CREATE TABLE core_identity.user_routing_groups (
    user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    group_name TEXT NOT NULL CHECK (length(group_name) BETWEEN 1 AND 64 AND group_name <> 'auto'),
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    source_reference TEXT NOT NULL CHECK (length(source_reference) BETWEEN 1 AND 200),
    PRIMARY KEY (user_id, group_name)
);
CREATE TABLE core_identity.developer_access (
    user_id BIGINT PRIMARY KEY REFERENCES core_identity.users(id),
    granted BOOLEAN NOT NULL,
    source_reference TEXT NOT NULL CHECK (length(source_reference) BETWEEN 1 AND 200),
    revision BIGINT NOT NULL DEFAULT 1 CHECK (revision > 0)
);
-- Revocations acquire the same user authority lock as financial admission.
-- Runtime roles have SELECT only on these grant tables. Policy revocation
-- therefore linearizes with in-flight requests without granting runtime UPDATE.
CREATE FUNCTION core_identity.routing_access_revoked() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        UPDATE core_identity.users SET auth_version=auth_version+1 WHERE id=OLD.user_id;
        RETURN OLD;
    ELSIF TG_TABLE_NAME='developer_access' THEN
        IF OLD.granted AND NOT NEW.granted THEN
            UPDATE core_identity.users SET auth_version=auth_version+1 WHERE id=OLD.user_id;
        END IF;
    ELSIF OLD.enabled AND NOT NEW.enabled THEN
        UPDATE core_identity.users SET auth_version=auth_version+1 WHERE id=OLD.user_id;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER developer_access_revocation AFTER UPDATE OR DELETE
    ON core_identity.developer_access FOR EACH ROW EXECUTE FUNCTION core_identity.routing_access_revoked();
CREATE TRIGGER routing_group_revocation AFTER UPDATE OR DELETE
    ON core_identity.user_routing_groups FOR EACH ROW EXECUTE FUNCTION core_identity.routing_access_revoked();
CREATE FUNCTION core_identity.check_api_key_settings() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'key settings preserve credential history' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM core_identity.credentials
        WHERE id=NEW.credential_id AND kind='api_key') THEN
        RAISE EXCEPTION 'settings require an API key' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.credential_id,NEW.one_time_reveal,NEW.encrypted_secret)
       IS DISTINCT FROM (OLD.credential_id,OLD.one_time_reveal,OLD.encrypted_secret) THEN
        RAISE EXCEPTION 'recovery policy is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER api_key_settings_guard BEFORE INSERT OR UPDATE OR DELETE
    ON core_identity.api_key_settings
    FOR EACH ROW EXECUTE FUNCTION core_identity.check_api_key_settings();
CREATE TABLE core_identity.key_funding_rules (
    credential_id BIGINT NOT NULL REFERENCES core_identity.credentials(id),
    position SMALLINT NOT NULL CHECK (position BETWEEN 0 AND 15),
    payer_account_id BIGINT NOT NULL REFERENCES core_identity.accounts(id),
    PRIMARY KEY (credential_id, position),
    UNIQUE (credential_id, payer_account_id)
);
CREATE TABLE core_identity.credential_grants (
    credential_id BIGINT NOT NULL REFERENCES core_identity.credentials(id),
    team_id BIGINT NOT NULL REFERENCES core_identity.teams(id),
    team_version BIGINT NOT NULL CHECK (team_version > 0),
    membership_version BIGINT NOT NULL CHECK (membership_version >= 0),
    PRIMARY KEY (credential_id, team_id)
);
CREATE TABLE core_identity.invites (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    digest BYTEA NOT NULL UNIQUE CHECK (octet_length(digest) = 32),
    team_id BIGINT NOT NULL REFERENCES core_identity.teams(id),
    team_version BIGINT NOT NULL CHECK (team_version > 0),
    recipient_user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    recipient_version BIGINT NOT NULL CHECK (recipient_version >= 0),
    inviter_credential_id BIGINT NOT NULL REFERENCES core_identity.credentials(id),
    inviter_membership_version BIGINT NOT NULL CHECK (inviter_membership_version >= 0),
    role TEXT NOT NULL CHECK (role IN ('admin', 'member')),
    can_spend BOOLEAN NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    accepted_at TIMESTAMPTZ,
    rejected_at TIMESTAMPTZ,
    withdrawn_at TIMESTAMPTZ,
    CHECK (num_nonnulls(accepted_at, rejected_at, withdrawn_at) <= 1)
);
CREATE INDEX invites_recipient ON core_identity.invites(recipient_user_id, id)
    WHERE accepted_at IS NULL AND rejected_at IS NULL AND withdrawn_at IS NULL;
CREATE TABLE core_identity.audit (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    actor_user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    credential_id BIGINT REFERENCES core_identity.credentials(id),
    action TEXT NOT NULL CHECK (length(action) BETWEEN 1 AND 128),
    target JSONB NOT NULL CHECK (jsonb_typeof(target) = 'object'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX audit_actor ON core_identity.audit(actor_user_id, id);

-- Account-local subscription/wallet order is not a second ordered list of payers.
-- This is policy only, not a balance table or a completed billing engine.
CREATE SCHEMA core_billing;
CREATE TABLE core_billing.account_policies (
    account_id BIGINT PRIMARY KEY REFERENCES core_identity.accounts(id),
    preference TEXT NOT NULL DEFAULT 'wallet_only'
        CHECK (preference IN ('subscription_first', 'wallet_first', 'subscription_only', 'wallet_only')),
    revision BIGINT NOT NULL DEFAULT 1 CHECK (revision > 0)
);

-- Enforce ownership at the storage boundary. Current permissions are still
-- checked by Rust on every request; these constraints do not grant authority.
CREATE FUNCTION core_identity.check_credential_owner() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
DECLARE owner_kind TEXT; personal_id BIGINT;
BEGIN
    IF TG_OP = 'UPDATE' AND (NEW.user_id, NEW.owner_account_id, NEW.kind, NEW.digest, NEW.user_version, NEW.session_started_at, NEW.created_at)
        IS DISTINCT FROM (OLD.user_id, OLD.owner_account_id, OLD.kind, OLD.digest, OLD.user_version, OLD.session_started_at, OLD.created_at) THEN
        RAISE EXCEPTION 'credential identity is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
        RAISE EXCEPTION 'revocation is permanent' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.kind = 'session' AND NEW.expires_at > OLD.expires_at THEN
        RAISE EXCEPTION 'issue a new credential instead of extending expiry' USING ERRCODE = '23514';
    END IF;
    SELECT kind INTO STRICT owner_kind FROM core_identity.accounts WHERE id = NEW.owner_account_id;
    SELECT personal_account_id INTO STRICT personal_id FROM core_identity.users WHERE id = NEW.user_id;
    IF (owner_kind = 'personal' AND NEW.owner_account_id <> personal_id)
        OR (NEW.kind = 'session' AND NEW.owner_account_id <> personal_id)
        OR (owner_kind = 'team' AND NEW.personal_billing_preference IS NOT NULL) THEN
        RAISE EXCEPTION 'invalid credential owner' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER credential_owner BEFORE INSERT OR UPDATE ON core_identity.credentials
    FOR EACH ROW EXECUTE FUNCTION core_identity.check_credential_owner();

CREATE FUNCTION core_identity.check_funding_rule() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
DECLARE key_kind TEXT; owner_id BIGINT; owner_kind TEXT; payer_kind TEXT;
BEGIN
    SELECT c.kind, c.owner_account_id, a.kind INTO STRICT key_kind, owner_id, owner_kind
        FROM core_identity.credentials c JOIN core_identity.accounts a ON a.id = c.owner_account_id
        WHERE c.id = NEW.credential_id;
    SELECT kind INTO STRICT payer_kind FROM core_identity.accounts WHERE id = NEW.payer_account_id;
    IF key_kind <> 'api_key'
        OR (owner_kind = 'team' AND (NEW.position <> 0 OR NEW.payer_account_id <> owner_id))
        OR (payer_kind = 'personal' AND NEW.payer_account_id <> owner_id) THEN
        RAISE EXCEPTION 'invalid funding rule' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER funding_rule BEFORE INSERT OR UPDATE ON core_identity.key_funding_rules
    FOR EACH ROW EXECUTE FUNCTION core_identity.check_funding_rule();

-- Native login names are not email identities. OAuth never links by email.
CREATE TABLE core_identity.password_logins (
    login_name TEXT PRIMARY KEY CHECK (login_name ~ '^[a-z0-9][a-z0-9_.-]{2,63}$'),
    user_id BIGINT NOT NULL UNIQUE REFERENCES core_identity.users(id),
    password_hash TEXT NOT NULL CHECK (length(password_hash) BETWEEN 40 AND 512),
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE core_identity.oauth_identities (
    issuer TEXT NOT NULL CHECK (issuer IN ('https://accounts.google.com','https://github.com','https://connect.linux.do','https://discord.com')),
    subject TEXT NOT NULL CHECK (length(subject) BETWEEN 1 AND 255),
    user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    PRIMARY KEY (issuer, subject),
    UNIQUE (user_id, issuer)
);
CREATE TABLE core_identity.oauth_flows (
    state_digest BYTEA PRIMARY KEY CHECK (octet_length(state_digest) = 32),
    binding_digest BYTEA NOT NULL CHECK (octet_length(binding_digest) = 32),
    nonce_digest BYTEA NOT NULL CHECK (octet_length(nonce_digest) = 32),
    -- The verifier is required for the one-time code exchange, then deleted.
    pkce_verifier TEXT NOT NULL CHECK (length(pkce_verifier) BETWEEN 43 AND 128),
    expires_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp() + interval '10 minutes',
    issuer TEXT NOT NULL DEFAULT 'https://accounts.google.com'
        CHECK (issuer IN ('https://accounts.google.com','https://github.com','https://connect.linux.do','https://discord.com'))
);
CREATE INDEX oauth_flows_expiry ON core_identity.oauth_flows(expires_at);
CREATE TABLE core_identity.auth_attempts (
    bucket BYTEA PRIMARY KEY CHECK (octet_length(bucket) = 32),
    started_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    attempts INTEGER NOT NULL CHECK (attempts BETWEEN 1 AND 10001)
);
CREATE INDEX auth_attempts_expiry ON core_identity.auth_attempts(started_at);

-- These are fresh-install invariants, not a migration or a second authority.
CREATE FUNCTION core_identity.protect_team() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'close teams instead of deleting their ownership history' USING ERRCODE = '23514';
    END IF;
    IF (NEW.id,NEW.account_id,NEW.created_by_user_id) IS DISTINCT FROM
       (OLD.id,OLD.account_id,OLD.created_by_user_id)
       OR NEW.version < OLD.version
       OR (NOT OLD.active AND NEW.active)
       OR ((NEW.owner_user_id,NEW.active,NEW.name) IS DISTINCT FROM
           (OLD.owner_user_id,OLD.active,OLD.name) AND NEW.version <= OLD.version) THEN
        RAISE EXCEPTION 'invalid team generation or immutable creator' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER protect_team BEFORE UPDATE OR DELETE ON core_identity.teams
    FOR EACH ROW EXECUTE FUNCTION core_identity.protect_team();
CREATE FUNCTION core_identity.protect_membership() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'membership generations cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF (NEW.team_id,NEW.user_id) IS DISTINCT FROM (OLD.team_id,OLD.user_id)
       OR NEW.version < OLD.version
       OR ((NEW.role,NEW.can_spend,NEW.active) IS DISTINCT FROM
           (OLD.role,OLD.can_spend,OLD.active) AND NEW.version <= OLD.version) THEN
        RAISE EXCEPTION 'invalid membership generation' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER protect_membership BEFORE UPDATE OR DELETE ON core_identity.memberships
    FOR EACH ROW EXECUTE FUNCTION core_identity.protect_membership();
CREATE FUNCTION core_identity.check_owner_membership() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
DECLARE tid BIGINT;
BEGIN
    IF TG_TABLE_NAME = 'teams' THEN tid := NEW.id; ELSE tid := NEW.team_id; END IF;
    IF EXISTS (SELECT 1 FROM core_identity.teams t JOIN core_identity.memberships m
        ON m.team_id=t.id AND m.user_id=t.owner_user_id WHERE t.id=tid AND m.active) THEN
        RAISE EXCEPTION 'owner cannot also have an active membership' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER team_owner_membership AFTER INSERT OR UPDATE ON core_identity.teams
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION core_identity.check_owner_membership();
CREATE CONSTRAINT TRIGGER member_owner_membership AFTER INSERT OR UPDATE ON core_identity.memberships
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION core_identity.check_owner_membership();
CREATE FUNCTION core_identity.protect_invite_terminal() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF num_nonnulls(OLD.accepted_at,OLD.rejected_at,OLD.withdrawn_at) > 0 AND
       (NEW.accepted_at,NEW.rejected_at,NEW.withdrawn_at) IS DISTINCT FROM
       (OLD.accepted_at,OLD.rejected_at,OLD.withdrawn_at) THEN
        RAISE EXCEPTION 'completed invitations cannot be reopened' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER invite_terminal BEFORE UPDATE ON core_identity.invites
    FOR EACH ROW EXECUTE FUNCTION core_identity.protect_invite_terminal();

-- Account identity and authorization generations cannot be rewound.
CREATE FUNCTION core_identity.protect_user() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF (NEW.id, NEW.personal_account_id) IS DISTINCT FROM (OLD.id, OLD.personal_account_id)
        OR NEW.auth_version < OLD.auth_version THEN
        RAISE EXCEPTION 'invalid user identity or authorization generation' USING ERRCODE = '23514';
    END IF;
    IF (NEW.active, NEW.platform_role) IS DISTINCT FROM (OLD.active, OLD.platform_role)
        AND NEW.auth_version = OLD.auth_version THEN
        NEW.auth_version := OLD.auth_version + 1;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER user_identity BEFORE UPDATE ON core_identity.users
    FOR EACH ROW EXECUTE FUNCTION core_identity.protect_user();


-- Dashboard compatibility metadata is not a financial projection or authority.
-- Imported credentials must explicitly opt in to legacy bcrypt verification.
CREATE TABLE core_identity.user_profiles (
    user_id BIGINT PRIMARY KEY REFERENCES core_identity.users(id),
    username TEXT NOT NULL UNIQUE CHECK (length(username) BETWEEN 1 AND 128),
    display_name TEXT NOT NULL DEFAULT '' CHECK (length(display_name) <= 256),
    email TEXT NOT NULL DEFAULT '' CHECK (length(email) <= 320),
    email_login_allowed BOOLEAN NOT NULL DEFAULT FALSE,
    setting TEXT NOT NULL DEFAULT '{}' CHECK (length(setting) <= 65536),
    password_login_allowed BOOLEAN NOT NULL DEFAULT TRUE,
    second_factor_required BOOLEAN NOT NULL DEFAULT FALSE,
    legacy_bcrypt_allowed BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX user_profiles_email ON core_identity.user_profiles(email) WHERE email <> '';
-- Invoice identity is private user-owned data, never an authorization grant.
CREATE TABLE core_identity.company_billing_profiles (
    user_id BIGINT PRIMARY KEY REFERENCES core_identity.users(id),
    country TEXT NOT NULL CHECK (country ~ '^[A-Z]{2}$'),
    is_business BOOLEAN NOT NULL,
    postcode TEXT NOT NULL CHECK (length(postcode)<=32),
    state TEXT NOT NULL CHECK (length(state)<=128),
    business_name TEXT NOT NULL CHECK (length(business_name)<=255),
    tax_id TEXT NOT NULL CHECK (length(tax_id)<=64),
    use_for_invoices BOOLEAN NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL CHECK(updated_at>=created_at)
);

-- Stable browser family and rotating refresh credentials remain separate from
-- the 15-minute bearer. Only hashes are stored; no production sessions import.
CREATE TABLE core_identity.web_sessions (
    sid TEXT PRIMARY KEY CHECK (sid ~ '^[a-f0-9]{64}$'),
    user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    user_version BIGINT NOT NULL CHECK (user_version > 0),
    current_credential_id BIGINT NOT NULL UNIQUE REFERENCES core_identity.credentials(id),
    refresh_digest BYTEA NOT NULL CHECK (octet_length(refresh_digest) = 32),
    previous_refresh_digest BYTEA CHECK (octet_length(previous_refresh_digest) = 32),
    previous_valid_until TIMESTAMPTZ,
    ip TEXT NOT NULL CHECK (length(ip) <= 128),
    user_agent TEXT NOT NULL CHECK (length(user_agent) <= 1024),
    weekly_logout BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
    last_active_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
    expires_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp() + interval '30 days',
    revoked_at TIMESTAMPTZ,
    CHECK (expires_at <= created_at + interval '30 days')
);
CREATE INDEX web_sessions_user ON core_identity.web_sessions(user_id);

-- Account security-policy changes invalidate every previously issued bearer
-- and browser family, including native endpoints, in the same transaction.
-- Opening the password gate for a still-dormant imported privileged account is
-- owned by the offline activation UPDATE on users.auth_version; do not +1 here
-- or activation would become +2.
CREATE FUNCTION core_identity.profile_policy_changed() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF (NEW.password_login_allowed,NEW.second_factor_required) IS DISTINCT FROM
       (OLD.password_login_allowed,OLD.second_factor_required) THEN
        IF NEW.password_login_allowed AND NOT OLD.password_login_allowed
           AND NEW.second_factor_required IS NOT DISTINCT FROM OLD.second_factor_required
           AND core_identity.is_identity_relation_owner()
           AND EXISTS (
                SELECT 1 FROM core_identity.privileged_import_facts f
                JOIN core_identity.users u ON u.id = NEW.user_id
                WHERE f.user_id = NEW.user_id AND NOT u.active
           ) THEN
            RETURN NEW;
        END IF;
        UPDATE core_identity.users SET auth_version=auth_version+1 WHERE id=NEW.user_id;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER profile_policy_generation AFTER UPDATE ON core_identity.user_profiles
    FOR EACH ROW EXECUTE FUNCTION core_identity.profile_policy_changed();

-- Retain only a one-way historical binding for logout. A rotated bearer stays
-- revoked for every authorization path, but can revoke its own stable family
-- until that original short-lived bearer expires.
CREATE TABLE core_identity.web_session_credentials (
    credential_id BIGINT PRIMARY KEY REFERENCES core_identity.credentials(id),
    sid TEXT NOT NULL REFERENCES core_identity.web_sessions(sid)
);
CREATE INDEX web_session_credentials_family ON core_identity.web_session_credentials(sid);
CREATE FUNCTION core_identity.check_web_session_credential() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'browser credential binding is append-only' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.credential_id,NEW.sid) IS DISTINCT FROM
       (OLD.credential_id,OLD.sid) THEN
        RAISE EXCEPTION 'browser credential binding is immutable' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM core_identity.credentials c
        JOIN core_identity.web_sessions s ON s.sid=NEW.sid
        WHERE c.id=NEW.credential_id AND c.kind='session'
          AND c.user_id=s.user_id AND c.user_version=s.user_version
          AND c.expires_at<=s.expires_at
    ) THEN
        RAISE EXCEPTION 'invalid browser credential binding' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER web_credential_binding BEFORE INSERT OR UPDATE OR DELETE
    ON core_identity.web_session_credentials
    FOR EACH ROW EXECUTE FUNCTION core_identity.check_web_session_credential();
CREATE TRIGGER web_credential_binding_truncate BEFORE TRUNCATE
    ON core_identity.web_session_credentials
    FOR EACH STATEMENT EXECUTE FUNCTION core_identity.check_web_session_credential();


-- Native MFA is installed explicitly. Ordinary startup only checks this contract.
CREATE TABLE core_identity.mfa_factors (
 user_id BIGINT PRIMARY KEY REFERENCES core_identity.users(id),
 revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),
 enabled BOOLEAN NOT NULL DEFAULT FALSE,
 key_id TEXT CHECK(length(key_id) BETWEEN 1 AND 64),
 encrypted_secret BYTEA CHECK(octet_length(encrypted_secret) BETWEEN 49 AND 2048),
 last_used_step BIGINT CHECK(last_used_step>=0),
 failed_attempts INTEGER NOT NULL DEFAULT 0 CHECK(failed_attempts BETWEEN 0 AND 5),
 locked_until TIMESTAMPTZ,
 CHECK((enabled AND key_id IS NOT NULL AND encrypted_secret IS NOT NULL) OR
       (NOT enabled AND key_id IS NULL AND encrypted_secret IS NULL))
);
CREATE TABLE core_identity.mfa_enrollments (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
 user_version BIGINT NOT NULL CHECK(user_version>0),
 source_credential_id BIGINT NOT NULL REFERENCES core_identity.credentials(id),
 sid TEXT REFERENCES core_identity.web_sessions(sid),
 key_id TEXT NOT NULL CHECK(length(key_id) BETWEEN 1 AND 64),
 encrypted_secret BYTEA NOT NULL CHECK(octet_length(encrypted_secret) BETWEEN 49 AND 2048),
 backup_verifiers TEXT[] NOT NULL CHECK(cardinality(backup_verifiers)=4),
 created_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
 expires_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp()+interval '600 seconds',
 consumed_at TIMESTAMPTZ,
 revoked_at TIMESTAMPTZ,
 CHECK(expires_at>created_at AND expires_at<=created_at+interval '600 seconds')
);
CREATE UNIQUE INDEX mfa_pending_enrollment ON core_identity.mfa_enrollments(user_id)
 WHERE consumed_at IS NULL AND revoked_at IS NULL;
CREATE TABLE core_identity.mfa_backup_codes (
 id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
 factor_revision BIGINT NOT NULL CHECK(factor_revision>0),
 verifier TEXT NOT NULL CHECK(length(verifier) BETWEEN 32 AND 1024),
 consumed_at TIMESTAMPTZ
);
CREATE INDEX mfa_backup_user ON core_identity.mfa_backup_codes(user_id,factor_revision);
CREATE TABLE core_identity.mfa_challenges (
 digest BYTEA PRIMARY KEY CHECK(octet_length(digest)=32),
 user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
 user_version BIGINT NOT NULL CHECK(user_version>0),
 factor_revision BIGINT NOT NULL CHECK(factor_revision>0),
 purpose TEXT NOT NULL CHECK(purpose IN ('native_password_login','browser_password_login')),
 binding_digest BYTEA CHECK(octet_length(binding_digest)=32),
 ip TEXT NOT NULL DEFAULT '' CHECK(length(ip)<=128),
 user_agent TEXT NOT NULL DEFAULT '' CHECK(length(user_agent)<=1024),
 attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),
 created_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
 expires_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp()+interval '300 seconds',
 consumed_at TIMESTAMPTZ,
 CHECK(expires_at>created_at AND expires_at<=created_at+interval '300 seconds'),
 CHECK((purpose='browser_password_login')=(binding_digest IS NOT NULL))
);
CREATE INDEX mfa_challenge_user ON core_identity.mfa_challenges(user_id);
CREATE TABLE core_identity.session_authentication (
 credential_id BIGINT PRIMARY KEY REFERENCES core_identity.credentials(id),
 user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
 user_version BIGINT NOT NULL CHECK(user_version>0),
 factor_revision BIGINT NOT NULL CHECK(factor_revision>=0),
 factor_level SMALLINT NOT NULL,
 method TEXT NOT NULL,
 authenticated_at TIMESTAMPTZ NOT NULL,
 mfa_verified_at TIMESTAMPTZ,
 CHECK((factor_level=1 AND method='primary' AND mfa_verified_at IS NULL) OR
       (factor_level=2 AND method IN ('totp','recovery') AND mfa_verified_at IS NOT NULL))
);
CREATE FUNCTION core_identity.check_session_authentication() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'session authentication is append-only' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM core_identity.credentials c WHERE c.id=NEW.credential_id
   AND c.kind='session' AND c.user_id=NEW.user_id AND c.user_version=NEW.user_version) THEN
  RAISE EXCEPTION 'invalid session authentication binding' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER session_authentication_immutable BEFORE INSERT OR UPDATE OR DELETE
 ON core_identity.session_authentication FOR EACH ROW EXECUTE FUNCTION core_identity.check_session_authentication();
CREATE TRIGGER session_authentication_truncate BEFORE TRUNCATE
 ON core_identity.session_authentication FOR EACH STATEMENT EXECUTE FUNCTION core_identity.check_session_authentication();
REVOKE ALL ON core_identity.mfa_factors,core_identity.mfa_enrollments,
 core_identity.mfa_backup_codes,core_identity.mfa_challenges,core_identity.session_authentication FROM PUBLIC;

-- Persisted import facts for one privileged account. Written only by the A2
-- importer in the same transaction as users/profiles; activation reads them and
-- never accepts caller-declared substitutes. Source enabled / global password
-- flags are archive facts; live users stay dormant until owner apply.
-- a2_sql_sha256 is the SHA-256 of the pre-seal base import SQL body (with the
-- SQL-body digest field held as 64 zero hex digits during hashing), not the
-- SHA-256 of the sealed complete SQL file.
CREATE TABLE core_identity.privileged_import_facts (
    user_id BIGINT PRIMARY KEY REFERENCES core_identity.users(id),
    archive_sha256 BYTEA NOT NULL CHECK (octet_length(archive_sha256) = 32),
    a2_semantic_sha256 BYTEA NOT NULL CHECK (octet_length(a2_semantic_sha256) = 32),
    a2_file_sha256 BYTEA NOT NULL CHECK (octet_length(a2_file_sha256) = 32),
    a2_sql_sha256 BYTEA NOT NULL CHECK (octet_length(a2_sql_sha256) = 32),
    migration_id TEXT NOT NULL CHECK (length(migration_id) BETWEEN 1 AND 128),
    system_id BYTEA NOT NULL CHECK (octet_length(system_id) = 32),
    database_oid BIGINT NOT NULL CHECK (database_oid > 0),
    instance_nonce BYTEA NOT NULL CHECK (octet_length(instance_nonce) = 32),
    import_run BYTEA NOT NULL CHECK (octet_length(import_run) = 32),
    source_enabled BOOLEAN NOT NULL,
    source_deleted BOOLEAN NOT NULL,
    password_verifier_recognized BOOLEAN NOT NULL,
    password_login_enabled BOOLEAN NOT NULL,
    password_hash_sha256 BYTEA NOT NULL CHECK (octet_length(password_hash_sha256) = 32),
    login_name_sha256 BYTEA NOT NULL CHECK (octet_length(login_name_sha256) = 32),
    source_role TEXT NOT NULL CHECK (source_role IN ('admin', 'superadmin')),
    source_second_factor_required BOOLEAN NOT NULL,
    source_auth_version BIGINT NOT NULL CHECK (source_auth_version > 0),
    UNIQUE (migration_id, user_id)
);
CREATE TABLE core_identity.permission_policies (
    user_id BIGINT PRIMARY KEY REFERENCES core_identity.users(id),
    revision BIGINT NOT NULL CHECK (revision > 0),
    contract TEXT NOT NULL CHECK (contract = 'core.permissions.v1'),
    sha256 BYTEA NOT NULL CHECK (octet_length(sha256) = 32),
    canonical_payload BYTEA NOT NULL CHECK (octet_length(canonical_payload) BETWEEN 1 AND 65536),
    verified_complete BOOLEAN NOT NULL CHECK (verified_complete)
);
CREATE TABLE core_identity.permission_policy_rows (
    user_id BIGINT NOT NULL REFERENCES core_identity.permission_policies(user_id),
    action TEXT NOT NULL,
    effect TEXT NOT NULL CHECK (effect IN ('allow', 'deny')),
    PRIMARY KEY (user_id, action)
);
CREATE TABLE core_identity.admin_activation_receipts (
    approval_id BYTEA PRIMARY KEY CHECK (octet_length(approval_id) = 32),
    payload_sha256 BYTEA NOT NULL CHECK (octet_length(payload_sha256) = 32),
    user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
    expected_auth_version BIGINT NOT NULL CHECK (expected_auth_version > 0),
    UNIQUE (user_id, expected_auth_version)
);
