CREATE FUNCTION core_bounties.guard_project() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE old_slot JSONB; new_slot JSONB; old_claim JSONB; new_claim JSONB;
BEGIN
 IF NEW.id<>OLD.id OR (NEW.body-'status'-'slots'-'claims'-'revision') IS DISTINCT FROM (OLD.body-'status'-'slots'-'claims'-'revision')
    OR jsonb_typeof(NEW.body->'revision') IS DISTINCT FROM 'number'
    OR (NEW.body->>'revision')::numeric IS DISTINCT FROM coalesce((OLD.body->>'revision')::numeric,0)+1
    OR jsonb_array_length(NEW.body->'slots')<>jsonb_array_length(OLD.body->'slots') THEN
  RAISE EXCEPTION 'bounty funding basis is immutable' USING ERRCODE='23514';
 END IF;
 FOR old_slot IN SELECT value FROM jsonb_array_elements(OLD.body->'slots') LOOP
  SELECT value INTO new_slot FROM jsonb_array_elements(NEW.body->'slots') WHERE value->'hold'=old_slot->'hold';
  IF new_slot IS NULL OR (new_slot-'paid') IS DISTINCT FROM (old_slot-'paid') OR jsonb_typeof(new_slot->'paid') IS DISTINCT FROM 'boolean' OR (old_slot->>'paid'='true' AND new_slot->>'paid' IS DISTINCT FROM 'true') THEN
   RAISE EXCEPTION 'bounty hold basis is immutable' USING ERRCODE='23514';
  END IF;
 END LOOP;
 FOR old_claim IN SELECT value FROM jsonb_array_elements(OLD.body->'claims') LOOP
  SELECT value INTO new_claim FROM jsonb_array_elements(NEW.body->'claims') WHERE value->'id'=old_claim->'id';
  IF new_claim IS NULL OR new_claim->'user' IS DISTINCT FROM old_claim->'user' OR new_claim->'account' IS DISTINCT FROM old_claim->'account' THEN
   RAISE EXCEPTION 'bounty claim recipient is immutable' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NEW;
END $$;
CREATE TRIGGER project_basis BEFORE UPDATE ON core_bounties.projects FOR EACH ROW EXECUTE FUNCTION core_bounties.guard_project();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA core_bounties FROM PUBLIC;
CREATE FUNCTION core_bounties.guard_confirmation() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF (to_jsonb(NEW)-'approved'-'csrf'-'browser_sid') IS DISTINCT FROM (to_jsonb(OLD)-'approved'-'csrf'-'browser_sid') OR (OLD.approved AND NOT NEW.approved) THEN
  RAISE EXCEPTION 'bounty confirmation basis is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER confirmation_basis BEFORE UPDATE ON core_bounties.confirmations FOR EACH ROW EXECUTE FUNCTION core_bounties.guard_confirmation();
REVOKE ALL ON FUNCTION core_bounties.guard_confirmation() FROM PUBLIC;

CREATE INDEX confirmations_operation_actor ON core_bounties.confirmations(actor,(request->>'operation_id'),expires DESC);

-- Freeze a native publication only around its own newly posted reservations.
CREATE FUNCTION core_bounties.guard_initial_project() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE op TEXT; owner_id BIGINT; payer BIGINT; net BIGINT; gross BIGINT; fee BIGINT;
        n INTEGER; i INTEGER; hold_id BIGINT; bps BIGINT; fee_account BIGINT; slot JSONB;
        expected_key TEXT; found BOOLEAN;
BEGIN
 op:=NEW.body->>'publication_operation'; owner_id:=(NEW.body->>'owner')::bigint;
 payer:=(NEW.body->>'payer')::bigint; net:=(NEW.body->>'net')::bigint;
 gross:=(NEW.body->>'gross')::bigint; fee:=(NEW.body->>'fee')::bigint;
 IF op IS NULL OR op !~ '^[A-Za-z0-9_.:-]{1,128}$' OR NEW.id !~ '^[A-Za-z0-9_.:-]{1,128}$'
    OR jsonb_typeof(NEW.body->'slots') IS DISTINCT FROM 'array'
    OR NEW.body->'claims' IS DISTINCT FROM '[]'::jsonb
    OR NEW.body->>'status' IS DISTINCT FROM 'published'
    OR NEW.body->'revision' IS DISTINCT FROM '1'::jsonb
    OR net IS NULL OR net<=0 OR gross IS NULL OR gross<=0 OR fee IS NULL OR fee<0
    OR jsonb_typeof(NEW.body->'published_at') IS DISTINCT FROM 'number'
    OR (NEW.body->>'published_at')::numeric NOT BETWEEN floor(extract(epoch FROM transaction_timestamp()))-1 AND ceil(extract(epoch FROM clock_timestamp()))
    OR NEW.body->>'consumption' IS DISTINCT FROM 'bounty:'||encode(sha256(convert_to(to_json(op)::text,'UTF8')),'hex')
    OR NOT EXISTS(SELECT FROM core_identity.users u JOIN core_identity.accounts a ON a.id=u.personal_account_id
                  WHERE u.id=owner_id AND a.id=payer AND a.kind='personal' AND u.active AND a.active) THEN
  RAISE EXCEPTION 'invalid initial bounty funding basis' USING ERRCODE='23514';
 END IF;
 n:=jsonb_array_length(NEW.body->'slots');
 IF n NOT BETWEEN 1 AND 100 OR (SELECT count(DISTINCT value->'hold') FROM jsonb_array_elements(NEW.body->'slots'))<>n THEN
  RAISE EXCEPTION 'invalid initial bounty slots' USING ERRCODE='23514';
 END IF;
 SELECT (c.policy->>0)::bigint,(c.policy->>1)::bigint INTO bps,fee_account
 FROM core_bounties.confirmations c
 WHERE c.actor=owner_id AND c.approved AND c.expires>=floor(extract(epoch FROM transaction_timestamp()))
   AND c.request->>'operation_id'=op AND c.request->>'action'='publish' AND c.request->>'project_id'=NEW.id
   AND (c.request->>'reward_credit')::bigint=gross AND (c.request->>'reward_slots')::bigint=n
   AND regexp_replace(rtrim(c.request->>'repository_url','/'),'(\.git)+$','')=NEW.body->>'repository'
 ORDER BY c.expires DESC,c.id DESC LIMIT 1;
 IF bps IS NULL OR bps NOT BETWEEN 0 AND 9999 OR fee_account IS NULL
    OR (NEW.body->>'fee_bps')::bigint IS DISTINCT FROM bps
    OR net::numeric<>gross::numeric-ceil(gross::numeric*bps/10000)
    OR fee::numeric<>(gross::numeric-net)*n THEN
  RAISE EXCEPTION 'bounty publication lacks exact confirmed economics' USING ERRCODE='23514';
 END IF;
 FOR i IN 0..n-1 LOOP
  slot:=NEW.body->'slots'->i; hold_id:=(slot->>'hold')::bigint;
  expected_key:=encode(sha256(convert_to('["'||op||'","slot-'||i||'"]','UTF8')),'hex');
  SELECT EXISTS(SELECT FROM core_billing.ledger_journals j
     JOIN core_billing.ledger_accounts w ON w.id=j.payer_id
     JOIN core_billing.ledger_accounts r ON r.id=j.payee_id
     WHERE j.id=hold_id AND j.scope='core-bounty' AND j.operation_key=expected_key
       AND j.actor_user_id=owner_id AND j.kind='reserve' AND j.amount_units=net
       AND j.created_xid=pg_current_xact_id() AND j.reason=format('Bounty %s slot-%s',NEW.id,i)
       AND w.owner_account_id=payer AND w.bucket='wallet' AND r.owner_account_id=payer AND r.bucket='reserved'
       AND NOT EXISTS(SELECT FROM core_billing.ledger_journals f WHERE f.parent_journal_id=j.id)) INTO found;
  IF slot->'paid' IS DISTINCT FROM 'false'::jsonb OR NOT found THEN
   RAISE EXCEPTION 'bounty slot is not its original newly posted hold' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF fee>0 AND fee_account<>payer AND NOT EXISTS(
   SELECT FROM core_billing.ledger_journals j
   JOIN core_billing.ledger_accounts w ON w.id=j.payer_id JOIN core_billing.ledger_accounts r ON r.id=j.payee_id
   WHERE j.scope='core-bounty' AND j.operation_key=encode(sha256(convert_to('["'||op||'","fee"]','UTF8')),'hex')
     AND j.actor_user_id=owner_id AND j.kind='transfer' AND j.amount_units=fee
     AND j.created_xid=pg_current_xact_id() AND j.reason=format('Bounty %s fee',NEW.id)
     AND w.owner_account_id=payer AND w.bucket='wallet' AND r.owner_account_id=fee_account AND r.bucket='wallet') THEN
  RAISE EXCEPTION 'bounty publication fee lacks original payer journal' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER initial_project_basis BEFORE INSERT ON core_bounties.projects FOR EACH ROW EXECUTE FUNCTION core_bounties.guard_initial_project();
REVOKE ALL ON FUNCTION core_bounties.guard_initial_project() FROM PUBLIC;

-- Additive component 25. Explicit owner installation/upgrade only; never startup.
-- These are price-entitlement facts, NOT wallet balances or another money ledger.
CREATE SCHEMA core_trust_pricing;
CREATE TABLE core_trust_pricing.policies (
    singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(singleton),
    revision BIGINT NOT NULL CHECK(revision>0),
    spec JSONB NOT NULL CHECK(jsonb_typeof(spec)='object'),
    source_digest BYTEA NOT NULL CHECK(octet_length(source_digest)=32),
    source_cutoff BIGINT NOT NULL CHECK(source_cutoff BETWEEN 0 AND 253402300799),
    -- The owner sets this only after the complete original-user import. Missing
    -- legacy rows fail closed; future, genuinely native identities can start L0.
    native_user_floor BIGINT NOT NULL CHECK(native_user_floor>0)
);
CREATE TABLE core_trust_pricing.user_bases (
    user_id BIGINT PRIMARY KEY REFERENCES core_identity.users(id),
    original_created_at BIGINT NOT NULL CHECK(original_created_at BETWEEN 0 AND 253402300799),
    console_activated_at BIGINT NOT NULL CHECK(console_activated_at BETWEEN 0 AND 253402300799),
    last_api_activity_at BIGINT NOT NULL CHECK(last_api_activity_at BETWEEN 0 AND 253402300799),
    override_level SMALLINT CHECK(override_level BETWEEN 0 AND 4),
    projection_known BOOLEAN NOT NULL,
    order_count BIGINT NOT NULL CHECK(order_count BETWEEN 0 AND 10000),
    revision BIGINT NOT NULL CHECK(revision>0),
    source_digest BYTEA NOT NULL CHECK(octet_length(source_digest)=32)
);
CREATE TABLE core_trust_pricing.legacy_paid_orders (
    source_order_id BIGINT PRIMARY KEY CHECK(source_order_id>0),
    user_id BIGINT NOT NULL REFERENCES core_trust_pricing.user_bases(user_id),
    -- Independently verified remaining NET credits, including an explicit zero
    -- for a fully refunded order. Owner corrections must carry new evidence.
    net_credits BIGINT NOT NULL CHECK(net_credits>=0),
    paid_at BIGINT NOT NULL CHECK(paid_at BETWEEN 1 AND 253402300799),
    revision BIGINT NOT NULL CHECK(revision>0),
    source_digest BYTEA NOT NULL CHECK(octet_length(source_digest)=32)
);
CREATE INDEX trust_paid_orders_user ON core_trust_pricing.legacy_paid_orders(user_id,source_order_id);
-- Runtime/Go/client cannot grant price rights. Revoke PUBLIC, including future
-- table privileges; the explicit runtime grant file adds only SELECT below.
REVOKE ALL ON SCHEMA core_trust_pricing FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA core_trust_pricing FROM PUBLIC;
-- Owner-installed native-origin fence: existing identities require explicit
-- imported bases, while post-install native registration needs no owner hook.
ALTER TABLE core_trust_pricing.policies ADD COLUMN native_since TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp();
INSERT INTO core_trust_pricing.policies(singleton,revision,spec,source_digest,source_cutoff,native_user_floor)
SELECT TRUE,1,'{"version":1,"paid_activation_enabled":true,"decay_period_days":90,"tiers":[{"level":0,"min_paid_credits":0,"discount":{"numerator":1,"denominator":1}},{"level":1,"min_paid_credits":500000,"discount":{"numerator":1,"denominator":1}},{"level":2,"min_paid_credits":5000000,"discount":{"numerator":97,"denominator":100}},{"level":3,"min_paid_credits":25000000,"discount":{"numerator":94,"denominator":100}},{"level":4,"min_paid_credits":100000000,"discount":{"numerator":9,"denominator":10}}],"admin_discount":{"numerator":9,"denominator":10},"superadmin_discount":{"numerator":9,"denominator":10}}'::jsonb,
    sha256(convert_to('core-native-trust-policy-v1','UTF8')),
    floor(extract(epoch FROM statement_timestamp()))::bigint,
    COALESCE((SELECT max(id) FROM core_identity.users),0)+1;
-- Serialize owner policy/basis changes against admitted price snapshots without
-- giving the runtime UPDATE privilege merely to use SELECT FOR SHARE.
CREATE FUNCTION core_trust_pricing.lock_owner_change() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(741803219);
    RETURN NULL;
END $$;
CREATE TRIGGER trust_policy_owner_lock BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON core_trust_pricing.policies
    FOR EACH STATEMENT EXECUTE FUNCTION core_trust_pricing.lock_owner_change();
CREATE TRIGGER trust_basis_owner_lock BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON core_trust_pricing.user_bases
    FOR EACH STATEMENT EXECUTE FUNCTION core_trust_pricing.lock_owner_change();
CREATE TRIGGER trust_order_owner_lock BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON core_trust_pricing.legacy_paid_orders
    FOR EACH STATEMENT EXECUTE FUNCTION core_trust_pricing.lock_owner_change();
REVOKE ALL ON FUNCTION core_trust_pricing.lock_owner_change() FROM PUBLIC;

-- Additive component 25 image price support; explicit owner install/upgrade.
-- Replace only the existing price CHECK and deferred charge-binding function.
-- Existing no-trust price JSON and immutable operation/charge bindings remain.
ALTER TABLE core_image.operations DROP CONSTRAINT operations_price_check;
ALTER TABLE core_image.operations ADD CONSTRAINT operations_price_check CHECK((
 (jsonb_typeof((price-'user_trust'))='object' AND jsonb_typeof((price-'user_trust')->'image')='object'
   AND ((price-'user_trust')->'image') ?& ARRAY['revision','rule','request','reservation_credits']
   AND ((price-'user_trust')->'image')-ARRAY['revision','rule','request','reservation_credits']='{}'::jsonb
   AND jsonb_typeof((price-'user_trust')#>'{image,reservation_credits}')='number'
   AND (price-'user_trust')#>>'{image,reservation_credits}' ~ '^(0|[1-9][0-9]{0,18})$'
   AND ((price-'user_trust')#>>'{image,reservation_credits}')::numeric<=9223372036854775807
   AND (price-'user_trust') ?& ARRAY['image','version','model','group','input_per_million','cached_per_million','output_per_million']
   AND (price-'user_trust')-ARRAY['image','upstream_cost_group_ppm','version','model','group','input_per_million','cached_per_million','output_per_million']='{}'::jsonb
   AND coalesce((price-'user_trust')->'upstream_cost_group_ppm','null'::jsonb)='null'::jsonb
   AND (price-'user_trust')->'input_per_million'='0'::jsonb AND (price-'user_trust')->'cached_per_million'='0'::jsonb AND (price-'user_trust')->'output_per_million'='0'::jsonb
   AND jsonb_typeof((price-'user_trust')->'version')='string' AND jsonb_typeof((price-'user_trust')->'model')='string' AND jsonb_typeof((price-'user_trust')->'group')='string') IS TRUE
 AND CASE
 WHEN NOT (price ? 'user_trust') THEN TRUE
 WHEN jsonb_typeof(price->'user_trust') IS DISTINCT FROM 'object' THEN FALSE
 ELSE (
  (price->'user_trust') ?& ARRAY['user_id','policy_revision','basis_revision','effective_level','level_source','discount','evaluated_at','evidence_digest']
  AND (price->'user_trust')-ARRAY['user_id','policy_revision','basis_revision','effective_level','level_source','discount','evaluated_at','next_decay_at','evidence_digest']='{}'::jsonb
  AND CASE WHEN
   jsonb_typeof(price#>'{user_trust,user_id}')='number'
   AND price#>>'{user_trust,user_id}' ~ '^[1-9][0-9]{0,18}$'
   AND jsonb_typeof(price#>'{user_trust,policy_revision}')='number'
   AND price#>>'{user_trust,policy_revision}' ~ '^[1-9][0-9]{0,18}$'
   AND jsonb_typeof(price#>'{user_trust,basis_revision}')='number'
   AND price#>>'{user_trust,basis_revision}' ~ '^(0|[1-9][0-9]{0,18})$'
   AND jsonb_typeof(price#>'{user_trust,effective_level}')='number'
   AND price#>>'{user_trust,effective_level}' ~ '^[0-6]$'
   AND jsonb_typeof(price#>'{user_trust,level_source}')='string'
   AND price#>>'{user_trust,level_source}' IN ('role','override','automatic')
   AND jsonb_typeof(price#>'{user_trust,evaluated_at}')='number'
   AND price#>>'{user_trust,evaluated_at}' ~ '^(0|[1-9][0-9]{0,11})$'
  THEN
   (price#>>'{user_trust,user_id}')::numeric<=9223372036854775807
   AND (price#>>'{user_trust,user_id}')::numeric=actor_user_id
   AND (price#>>'{user_trust,policy_revision}')::numeric<=9223372036854775807
   AND (price#>>'{user_trust,basis_revision}')::numeric<=9223372036854775807
   AND (price#>>'{user_trust,evaluated_at}')::numeric<=253402300799
   AND (((price#>>'{user_trust,effective_level}')::integer>=5)
        = (price#>>'{user_trust,level_source}'='role'))
   AND CASE
    WHEN NOT ((price->'user_trust') ? 'next_decay_at')
         OR price#>'{user_trust,next_decay_at}'='null'::jsonb THEN TRUE
    WHEN jsonb_typeof(price#>'{user_trust,next_decay_at}')='number'
         AND price#>>'{user_trust,next_decay_at}' ~ '^(0|[1-9][0-9]{0,11})$'
    THEN (price#>>'{user_trust,next_decay_at}')::numeric<=253402300799
         AND (price#>>'{user_trust,next_decay_at}')::numeric>(price#>>'{user_trust,evaluated_at}')::numeric
         AND price#>>'{user_trust,level_source}'='automatic'
    ELSE FALSE END
  ELSE FALSE END
  AND CASE WHEN jsonb_typeof(price#>'{user_trust,discount}')='object' THEN (
   (price#>'{user_trust,discount}') ?& ARRAY['numerator','denominator']
   AND (price#>'{user_trust,discount}')-ARRAY['numerator','denominator']='{}'::jsonb
   AND CASE WHEN
    jsonb_typeof(price#>'{user_trust,discount,numerator}')='number'
    AND price#>>'{user_trust,discount,numerator}' ~ '^[1-9][0-9]{0,18}$'
    AND jsonb_typeof(price#>'{user_trust,discount,denominator}')='number'
    AND price#>>'{user_trust,discount,denominator}' ~ '^[1-9][0-9]{0,18}$'
   THEN (price#>>'{user_trust,discount,numerator}')::numeric
          <=(price#>>'{user_trust,discount,denominator}')::numeric
        AND (price#>>'{user_trust,discount,denominator}')::numeric<=1000000000000000000
   ELSE FALSE END
  ) IS TRUE ELSE FALSE END
  AND CASE WHEN jsonb_typeof(price#>'{user_trust,evidence_digest}')='array'
  THEN jsonb_array_length(price#>'{user_trust,evidence_digest}')=32
       AND NOT jsonb_path_exists(price#>'{user_trust,evidence_digest}','$[*] ? (@.type() != "number" || @ < 0 || @ > 255 || @ % 1 != 0)')
       AND jsonb_path_exists(price#>'{user_trust,evidence_digest}','$[*] ? (@ > 0)')
  ELSE FALSE END
 ) IS TRUE
 END
) IS TRUE);

CREATE OR REPLACE FUNCTION core_image.check_charge_atomic() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE operation_id TEXT; operation RECORD; charge RECORD;
 image_price JSONB; ratio JSONB; ratio_name TEXT; part TEXT; raw_value TEXT;
 requested_n NUMERIC; maximum_n NUMERIC; max_budget NUMERIC;
 usd_num NUMERIC; usd_den NUMERIC; group_num NUMERIC; group_den NUMERIC;
 numerators NUMERIC[]; denominators NUMERIC[];
 gcd_a NUMERIC; gcd_b NUMERIC; remainder NUMERIC;
 base_numerator NUMERIC; base_denominator NUMERIC; base_credits NUMERIC;
 discounted_numerator NUMERIC; discounted_denominator NUMERIC;
 discounted_credits NUMERIC; trusted_reservation BIGINT; factor NUMERIC;
BEGIN
 IF TG_TABLE_SCHEMA='core_charging' THEN
  IF NEW.image_operation_id IS NULL THEN RETURN NULL; END IF;
  operation_id:=NEW.image_operation_id;
 ELSE operation_id:=NEW.id;
 END IF;
 SELECT o.* INTO operation FROM core_image.operations o WHERE o.id=operation_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'missing image operation source' USING ERRCODE='23514'; END IF;
 -- The old no-trust path is unchanged. New frozen evidence must also preserve
 -- the original Rust image quote's count, budget and base-overflow checks.
 -- Run before the no-charge return: previews must not persist an invalid base.
 IF operation.price ? 'user_trust' THEN
  image_price:=operation.price->'image';
  IF jsonb_typeof(image_price->'rule') IS DISTINCT FROM 'object'
     OR jsonb_typeof(image_price->'request') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid trusted image tariff shape' USING ERRCODE='23514';
  END IF;
  FOREACH ratio_name IN ARRAY ARRAY['usd_micros_per_image','group_multiplier'] LOOP
   ratio:=image_price#>ARRAY['rule',ratio_name];
   IF jsonb_typeof(ratio) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid trusted image ratio shape' USING ERRCODE='23514';
   END IF;
   IF NOT (ratio ?& ARRAY['numerator','denominator'])
      OR ratio-ARRAY['numerator','denominator']<>'{}'::jsonb THEN
    RAISE EXCEPTION 'invalid trusted image ratio fields' USING ERRCODE='23514';
   END IF;
   FOREACH part IN ARRAY ARRAY['numerator','denominator'] LOOP
    raw_value:=ratio->>part;
    IF jsonb_typeof(ratio->part) IS DISTINCT FROM 'number'
       OR raw_value !~ '^(0|[1-9][0-9]{0,19})$' THEN
     RAISE EXCEPTION 'invalid trusted image ratio integer' USING ERRCODE='23514';
    END IF;
    IF raw_value::numeric>18446744073709551615
       OR (part='denominator' AND raw_value::numeric=0) THEN
     RAISE EXCEPTION 'trusted image ratio outside u64 domain' USING ERRCODE='23514';
    END IF;
   END LOOP;
  END LOOP;
  IF jsonb_typeof(image_price#>'{request,n}') IS DISTINCT FROM 'number'
     OR image_price#>>'{request,n}' !~ '^[1-9][0-9]{0,2}$'
     OR jsonb_typeof(image_price#>'{rule,max_n}') IS DISTINCT FROM 'number'
     OR image_price#>>'{rule,max_n}' !~ '^[1-9][0-9]{0,2}$'
     OR jsonb_typeof(image_price#>'{rule,max_budget}') IS DISTINCT FROM 'number'
     OR image_price#>>'{rule,max_budget}' !~ '^(0|[1-9][0-9]{0,18})$' THEN
   RAISE EXCEPTION 'invalid trusted image count or budget integer' USING ERRCODE='23514';
  END IF;
  requested_n:=(image_price#>>'{request,n}')::numeric;
  maximum_n:=(image_price#>>'{rule,max_n}')::numeric;
  max_budget:=(image_price#>>'{rule,max_budget}')::numeric;
  IF requested_n>maximum_n OR maximum_n>128 OR max_budget>9223372036854775807 THEN
   RAISE EXCEPTION 'trusted image count or budget outside domain' USING ERRCODE='23514';
  END IF;
  usd_num:=(image_price#>>'{rule,usd_micros_per_image,numerator}')::numeric;
  usd_den:=(image_price#>>'{rule,usd_micros_per_image,denominator}')::numeric;
  group_num:=(image_price#>>'{rule,group_multiplier,numerator}')::numeric;
  group_den:=(image_price#>>'{rule,group_multiplier,denominator}')::numeric;
  -- Rust validates both the requested quote and the maximum configured count.
  -- Euclidean cancellation precedes each checked u128 base multiplication.
  FOR count_index IN 1..2 LOOP
   numerators:=ARRAY[usd_num,group_num,
       CASE WHEN count_index=1 THEN requested_n ELSE maximum_n END,500000::numeric];
   denominators:=ARRAY[usd_den,group_den,1000000::numeric];
   FOR numerator_index IN 1..4 LOOP
    FOR denominator_index IN 1..3 LOOP
     gcd_a:=numerators[numerator_index];
     gcd_b:=denominators[denominator_index];
     WHILE gcd_b<>0 LOOP
      remainder:=mod(gcd_a,gcd_b); gcd_a:=gcd_b; gcd_b:=remainder;
     END LOOP;
     numerators[numerator_index]:=div(numerators[numerator_index],gcd_a);
     denominators[denominator_index]:=div(denominators[denominator_index],gcd_a);
    END LOOP;
   END LOOP;
   base_numerator:=1; base_denominator:=1;
   FOREACH factor IN ARRAY numerators LOOP
    base_numerator:=base_numerator*factor;
    IF base_numerator>340282366920938463463374607431768211455 THEN
     RAISE EXCEPTION 'trusted image original numerator overflow' USING ERRCODE='23514';
    END IF;
   END LOOP;
   FOREACH factor IN ARRAY denominators LOOP
    base_denominator:=base_denominator*factor;
    IF base_denominator>340282366920938463463374607431768211455 THEN
     RAISE EXCEPTION 'trusted image original denominator overflow' USING ERRCODE='23514';
    END IF;
   END LOOP;
   base_credits:=div(base_numerator,base_denominator)
       + CASE WHEN mod(base_numerator,base_denominator)<>0 THEN 1 ELSE 0 END;
   IF base_credits>9223372036854775807 OR base_credits>max_budget
      OR (count_index=1 AND base_credits IS DISTINCT FROM
          (image_price->>'reservation_credits')::numeric) THEN
    RAISE EXCEPTION 'trusted image original reservation or budget mismatch' USING ERRCODE='23514';
   END IF;
  END LOOP;
  -- Multiply the trust factor into the complete exact amount. Never discount
  -- the already-rounded persisted base reservation, and never use numeric ceil
  -- on division whose scale may round away a nonzero remainder.
  discounted_numerator:=usd_num*group_num*requested_n*500000
      *(operation.price#>>'{user_trust,discount,numerator}')::numeric;
  discounted_denominator:=usd_den*group_den*1000000
      *(operation.price#>>'{user_trust,discount,denominator}')::numeric;
  discounted_credits:=div(discounted_numerator,discounted_denominator)
      + CASE WHEN mod(discounted_numerator,discounted_denominator)<>0 THEN 1 ELSE 0 END;
  IF discounted_credits>9223372036854775807 THEN
   RAISE EXCEPTION 'trusted image discounted reservation overflow' USING ERRCODE='23514';
  END IF;
  trusted_reservation:=discounted_credits::bigint;
 END IF;

 SELECT q.* INTO charge FROM core_charging.requests q WHERE q.image_operation_id=operation_id;
 IF NOT FOUND THEN
  IF operation.state NOT IN ('previewed','confirmed') OR operation.charge_id IS NOT NULL THEN
   RAISE EXCEPTION 'missing image charge' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
 END IF;
 IF charge.id<>operation.id OR charge.image_operation_id<>operation.id
    OR charge.actor_user_id<>operation.actor_user_id
    OR charge.owner_account_id<>operation.owner_account_id
    OR (operation.source_kind='drawing' AND (charge.key_id IS NOT NULL OR charge.payer_account_id<>operation.owner_account_id))
    OR (operation.source_kind='api_key' AND charge.key_id IS DISTINCT FROM operation.key_id)
    OR charge.oauth_source IS NOT NULL
    OR charge.assistant_grant_id IS NOT NULL OR charge.assistant_sponsor_account_id IS NOT NULL
    OR charge.fingerprint IS DISTINCT FROM operation.fingerprint OR charge.price IS DISTINCT FROM operation.price
    OR charge.reserved IS DISTINCT FROM (CASE WHEN operation.price ? 'user_trust' THEN trusted_reservation
       ELSE (operation.price#>>'{image,reservation_credits}')::bigint END)
    OR charge.input_tokens<>0 OR charge.cached_tokens<>0 OR charge.output_tokens<>0 THEN
  RAISE EXCEPTION 'image charge source mismatch' USING ERRCODE='23514';
 END IF;
 IF (operation.state='confirmed' AND (charge.state NOT IN ('reserved','released') OR operation.charge_id IS NOT NULL))
    OR (operation.state='dispatching' AND (charge.state NOT IN ('streaming','reconcile') OR operation.charge_id IS DISTINCT FROM charge.id))
    OR (operation.state='billing_pending' AND (charge.state NOT IN ('streaming','reconcile','settled') OR operation.charge_id IS DISTINCT FROM charge.id))
    OR operation.state='previewed'
    OR (operation.state='completed' AND charge.state<>'settled') THEN
  RAISE EXCEPTION 'image operation and charge states must commit together' USING ERRCODE='23514';
 END IF;
 IF charge.image_usage IS NOT NULL AND charge.image_usage IS DISTINCT FROM operation.image_usage THEN
  RAISE EXCEPTION 'image usage evidence mismatch' USING ERRCODE='23514';
 END IF;
 IF charge.state='settled' AND (operation.state NOT IN ('billing_pending','completed')
    OR operation.output IS NULL OR operation.image_usage IS DISTINCT FROM charge.image_usage
    OR charge.outcome IS DISTINCT FROM 'completed') THEN
  RAISE EXCEPTION 'image settlement requires durable original output receipt' USING ERRCODE='23514';
 END IF;
 IF operation.state='completed' AND (operation.charge_id IS DISTINCT FROM charge.id
    OR operation.settled_credits IS DISTINCT FROM charge.settled
    OR operation.image_usage IS DISTINCT FROM charge.image_usage
    OR operation.output IS NULL OR charge.outcome IS DISTINCT FROM 'completed') THEN
  RAISE EXCEPTION 'image output and completed settlement must commit together' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;

-- Native Telegram Widget identities and short-lived, browser-bound ceremonies.
-- Existing identity and trust-pricing component bytes remain unchanged.
CREATE SCHEMA core_telegram_auth;

-- A revoked subject remains owned by its original account. Unbinding must not
-- make that stable external identity available for another user's claim.
CREATE TABLE core_telegram_auth.bindings (
 subject TEXT PRIMARY KEY CHECK(subject ~ '^[1-9][0-9]{0,18}$' AND subject::numeric<=9223372036854775807),
 user_id BIGINT NOT NULL REFERENCES core_identity.users(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
 revoked_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX telegram_active_user ON core_telegram_auth.bindings(user_id)
 WHERE revoked_at IS NULL;

CREATE TABLE core_telegram_auth.flows (
 token_digest BYTEA PRIMARY KEY CHECK(octet_length(token_digest)=32),
 purpose TEXT NOT NULL CHECK(purpose IN ('login','bind')),
 binding_digest BYTEA NOT NULL CHECK(octet_length(binding_digest)=32),
 user_id BIGINT REFERENCES core_identity.users(id),
 user_version BIGINT CHECK(user_version>0),
 sid TEXT REFERENCES core_identity.web_sessions(sid),
 created_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
 expires_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp()+interval '300 seconds',
 consumed_at TIMESTAMPTZ,
 CHECK(expires_at>created_at AND expires_at<=created_at+interval '300 seconds'),
 CHECK((purpose='login' AND user_id IS NULL AND user_version IS NULL AND sid IS NULL)
    OR (purpose='bind' AND user_id IS NOT NULL AND user_version IS NOT NULL AND sid IS NOT NULL))
);
CREATE INDEX telegram_flow_expiry ON core_telegram_auth.flows(expires_at);

-- The legacy Widget does not sign an application nonce. One assertion claim
-- namespace is therefore shared by login and binding, beyond the flow cookie.
CREATE TABLE core_telegram_auth.assertions (
 digest BYTEA PRIMARY KEY CHECK(octet_length(digest)=32),
 created_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
 expires_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp()+interval '600 seconds',
 CHECK(expires_at>created_at AND expires_at<=created_at+interval '600 seconds')
);
CREATE INDEX telegram_assertion_expiry ON core_telegram_auth.assertions(expires_at);
REVOKE ALL ON SCHEMA core_telegram_auth FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA core_telegram_auth FROM PUBLIC;
